function tf_icon($name, $size = 22, $class = '') {
  $l = tf_icon_list(); $p = $l[$name] ?? $l['grid'];
  return '<svg class="ic ' . esc_attr($class) . '" width="' . (int)$size . '" height="' . (int)$size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $p . '</svg>';
}
